// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 initVal, uint256 newVal) public {
        vm.assume(initVal != newVal);

        // fix MinSum before initialization
        c.SetMinSum(initVal);

        // finalize initialization
        c.Initialized();

        // after initialization, any SetMinSum must revert and NOT change MinSum
        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.MinSum() == initVal);
    }
}
